  release text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),
  bank_backup jsonb NOT NULL,history_before jsonb,history_after jsonb);
ALTER TABLE public.lms_assessment_release_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.lms_assessment_release_audit FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION pg_temp.history_digest() RETURNS jsonb LANGUAGE plpgsql AS $fn$
DECLARE t text; digest text; n bigint; result jsonb:='{}';
BEGIN
  FOR t IN SELECT table_name FROM information_schema.tables
    WHERE table_schema='public' AND table_name IN (
      'exam_attempts','user_exam_scores','user_progress','certificates',
      'user_certificates','user_quiz_scores','quiz_attempts','lms_historical_approvals')
    AND table_type='BASE TABLE' ORDER BY table_name
  LOOP
    EXECUTE format('SELECT count(*),md5(coalesce(string_agg(to_jsonb(x)::text, %L ORDER BY to_jsonb(x)::text),%L)) FROM public.%I x','','',t) INTO n,digest;
    result:=result||jsonb_build_object(t,jsonb_build_object('rows',n,'md5',digest));
  END LOOP;
  RETURN result;
END $fn$;
DO $lock$
DECLARE t text;
BEGIN
  FOR t IN SELECT table_name FROM information_schema.tables
    WHERE table_schema='public' AND table_name IN (
      'exam_attempts','user_exam_scores','user_progress','certificates',
      'user_certificates','user_quiz_scores','quiz_attempts','lms_historical_approvals')
    AND table_type='BASE TABLE' ORDER BY table_name
  LOOP EXECUTE format('LOCK TABLE public.%I IN SHARE MODE',t); END LOOP;
END $lock$;
CREATE TEMP TABLE release_history_before ON COMMIT DROP AS SELECT pg_temp.history_digest() AS digest;

